/* 讲义原文是「一句一行」（从 PDF 抽出来的硬换行）。原来一律 join("<br>")，
   于是整段只有一个 <p>，`.body p` 的段距从来没生效过 —— 长卡就成了一堵墙。
   只有 opts.paragraphs 时才重排（AI 对话文本保持原来的 <br> 行为）：
   上一行以句末标点收尾、且下一行不是续行（以标点开头）→ 另起一段。 */
if (!(opts && opts.paragraphs)){
  out.push("<p>" + para.map(inline).join("<br>") + "</p>");
}else{
  var pgroups = [[para[0]]];
  for (var pgi = 1; pgi < para.length; pgi++){
    var gLast = pgroups[pgroups.length - 1];
    var prevLine = String(gLast[gLast.length - 1]).replace(/\s+$/, "");
    var prevEnds = /[。！？；：…”』」）)]$/.test(prevLine);
    var nextIsTail = /^\s*[，、；：。！？）」』…]/.test(para[pgi]);
    if (prevEnds && !nextIsTail) pgroups.push([para[pgi]]);
    else gLast.push(para[pgi]);
  }
  out.push(pgroups.map(function(g){
    return "<p>" + g.map(inline).join("<br>") + "</p>";
  }).join(""));
}
